public class Solution {
  // "定时消息 = 传时长"版：把 deliverAt - now 当成 delay 直接交给服务端，
  // 超过上限的那部分被静默截断 —— 订单提前关，或者按官方口径"定时不生效、立即投递"。
  public static int[] timerChain(int deliverAtMs, int nowMs, int horizonMs, int refireLeadMs) {
    if (horizonMs <= 0) throw new IllegalArgumentException("horizon must be positive");
    if (refireLeadMs < 0) throw new IllegalArgumentException("refire lead must be non-negative");
    long reach = (long) horizonMs - refireLeadMs;
    if (reach <= 0) throw new IllegalArgumentException("hop reach must be positive");
    if (nowMs < 0) throw new IllegalArgumentException("now must be non-negative");
    int hops = deliverAtMs <= nowMs ? 0 : 1;
    return new int[] {hops, Math.max(deliverAtMs, nowMs), deliverAtMs <= nowMs ? 1 : 0,
        Math.max(0, deliverAtMs - nowMs)};
  }
}
